import React from 'react';
import Reveal from './Reveal';
import SectionHeading from './SectionHeading';
import { projects, projectCategories } from '../data/content';

const groups = projectCategories
  .filter((cat) => cat.id !== 'all')
  .map((cat) => ({
    ...cat,
    items: projects.filter((p) => p.categories[0] === cat.id),
  }))
  .filter((group) => group.items.length > 0);

export default function Projects() {
  return (
    <section id="projects" className="py-16 px-6 border-t border-zinc-200 dark:border-zinc-800">
      <div className="max-w-prose mx-auto">
        <Reveal>
          <SectionHeading eyebrow="Projects" heading="Things I've built" />
        </Reveal>

        <div className="mt-8 space-y-8">
          {groups.map((group, gIdx) => (
            <div key={group.id}>
              <h3 className="text-sm font-medium text-zinc-500 dark:text-zinc-500 uppercase tracking-wide">
                {group.label}
              </h3>
              <div className="mt-3 divide-y divide-zinc-200 dark:divide-zinc-800">
                {group.items.map((project, idx) => (
                  <Reveal key={project.title} delay={(gIdx * 2 + idx) * 40}>
                    <div className="py-4 first:pt-0">
                      <div className="flex items-baseline justify-between gap-3 flex-wrap">
                        <h4 className="font-semibold text-zinc-900 dark:text-zinc-50">
                          {project.title}
                        </h4>
                        <span className="text-xs font-mono text-zinc-400 dark:text-zinc-600">
                          {project.status}
                        </span>
                      </div>
                      <p className="mt-1.5 text-sm text-zinc-600 dark:text-zinc-400 leading-relaxed">
                        {project.build}
                      </p>
                      <p className="mt-1 text-xs text-zinc-400 dark:text-zinc-600 italic">
                        {project.impact}
                      </p>
                      <p className="mt-1.5 text-xs font-mono text-zinc-400 dark:text-zinc-600">
                        {project.tech.join(' · ')}
                      </p>
                    </div>
                  </Reveal>
                ))}
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}
